    "rent-vs-buy": {
      eyebrow: "Five-year cost comparison",
      fields: [
        field("rent", "Monthly rent", 2200, { prefix: "$" }),
        field("price", "Home price", 42e4, { prefix: "$" }),
        field("downRate", "Down payment", 20, { suffix: "%" }),
        field("mortgageRate", "Mortgage rate", 6.25, { suffix: "%" }),
        field("years", "Comparison period", 5, { suffix: "years", min: 1 })
      ],
      formula: "Compare rent paid with mortgage interest, ownership costs, transaction costs, and estimated equity",
      assumptions: ["Ownership costs use 2% of home value per year.", "Buying and selling costs total 8%; appreciation is excluded."],
      calculate: ({ rent, price, downRate, mortgageRate, years }) => {
        const down = price * downRate / 100;
        const principal = price - down;
        const payment = loanPayment(principal, mortgageRate, 360);
        const months = Math.round(years * 12);
        let balance = principal;
        let interest = 0;
        const monthlyRate = mortgageRate / 100 / 12;
        for (let month = 0; month < months; month += 1) {
          const charge = balance * monthlyRate;
          interest += charge;
          balance -= Math.max(0, payment - charge);
        }
        const ownershipCost = interest + price * 0.02 * years + price * 0.08;
        const rentCost = rent * months;
        const winner = rentCost <= ownershipCost ? "Renting" : "Buying";
        const costDifference = Math.abs(rentCost - ownershipCost);
        const period = `${years} ${years === 1 ? "year" : "years"}`;
        return result(winner, `is estimated to cost ${money(costDifference)} less over ${period}`, [
          ["Rent paid", money(rentCost)],
          ["Estimated ownership cost", money(ownershipCost)],
          ["Estimated cost difference", money(costDifference)],
          ["Principal repaid", money(principal - balance)]
        ], "This is a simplified comparison. Change in home value is intentionally excluded.");
      }
    },
    "mortgage-extra-payment": {
      eyebrow: "Time and interest saved",
      fields: [
        field("principal", "Mortgage balance", 32e4, { prefix: "$" }),
        field("rate", "Interest rate", 6, { suffix: "%" }),
        field("years", "Remaining term", 28, { suffix: "years", min: 1 }),
        field("extra", "Extra monthly payment", 250, { prefix: "$" })
      ],
      formula: "Compare amortization with the scheduled payment and with an added monthly overpayment",
      assumptions: ["The rate remains fixed.", "Extra payments go directly to principal without penalty."],
      calculate: ({ principal, rate, years, extra }) => {
        const scheduled = loanPayment(principal, rate, years * 12);
        const simulate = (payment) => {
          let balance = principal;
          let interest = 0;
          let months = 0;
          const r = rate / 100 / 12;
          while (balance > 0.01 && months < years * 12 + 120) {
            const charge = balance * r;
            interest += charge;
            balance = Math.max(0, balance + charge - payment);
            months += 1;
          }
          return { months, interest };
        };
        const normal = simulate(scheduled);
        const faster = simulate(scheduled + extra);
        return result(monthsLabel(normal.months - faster.months), "time saved", [
          ["Interest saved", money(normal.interest - faster.interest)],
          ["New payoff time", monthsLabel(faster.months)],
          ["New monthly payment", money(scheduled + extra)]
        ]);
      }
    },
