  var clock = (minutes) => {
    const wholeMinutes = Math.max(0, minutes);
    const hours = Math.floor(wholeMinutes / 60);
    const mins = Math.floor(wholeMinutes % 60);
    const seconds = Math.round((wholeMinutes - Math.floor(wholeMinutes)) * 60);
    return [hours ? `${hours}h` : "", `${mins}m`, seconds ? `${seconds}s` : ""].filter(Boolean).join(" ");
  };
