  // calculum.dev/src/data/mortgage-vs-investing.js
  var EPSILON = 5e-3;
  function mortgagePayment(principal, annualRate, months) {
    const count = Math.max(1, Math.round(months));
    const rate = annualRate / 100 / 12;
    if (rate === 0) return principal / count;
    return principal * rate * (1 + rate) ** count / ((1 + rate) ** count - 1);
  }
  function investmentMonthlyRate(annualReturn, annualFee) {
    const netAnnualReturn = Math.max(-99, annualReturn - annualFee) / 100;
    return (1 + netAnnualReturn) ** (1 / 12) - 1;
  }
  function mortgageVsInvestingModel(values) {
    const balance = Math.max(0, Number(values.balance) || 0);
    const mortgageRate = Math.max(0, Number(values.mortgageRate) || 0);
    const remainingYears = Math.max(1, Number(values.remainingYears) || 1);
    const extraMonthly = Math.max(0, Number(values.extraMonthly) || 0);
    const investmentReturn = Math.max(-99, Number(values.investmentReturn) || 0);
    const fundFee = Math.max(0, Number(values.fundFee) || 0);
    const months = Math.max(1, Math.round(remainingYears * 12));
    const scheduledPayment = mortgagePayment(balance, mortgageRate, months);
    const monthlyMortgageRate = mortgageRate / 100 / 12;
    const monthlyInvestmentRate = investmentMonthlyRate(investmentReturn, fundFee);
    const monthlyBudget = scheduledPayment + extraMonthly;
    let mortgageFirstBalance = balance;
    let investFirstBalance = balance;
    let mortgageFirstInvestment = 0;
    let investFirstInvestment = 0;
    let mortgageFirstInterest = 0;
    let investFirstInterest = 0;
    let mortgageFirstPayoffMonth = balance <= EPSILON ? 0 : null;
    const points = [{
      month: 0,
      mortgageFirstNet: -balance,
      investFirstNet: -balance,
      mortgageFirstBalance: balance,
      investFirstBalance: balance
    }];
    for (let month = 1; month <= months; month += 1) {
      mortgageFirstInvestment *= 1 + monthlyInvestmentRate;
      investFirstInvestment *= 1 + monthlyInvestmentRate;
      if (mortgageFirstBalance > EPSILON) {
        const interest = mortgageFirstBalance * monthlyMortgageRate;
        const amountDue = mortgageFirstBalance + interest;
        const mortgagePaymentMade = Math.min(monthlyBudget, amountDue);
        mortgageFirstInterest += interest;
        mortgageFirstBalance = Math.max(0, amountDue - mortgagePaymentMade);
        mortgageFirstInvestment += monthlyBudget - mortgagePaymentMade;
        if (mortgageFirstBalance <= EPSILON) {
          mortgageFirstBalance = 0;
          mortgageFirstPayoffMonth = month;
        }
      } else {
        mortgageFirstInvestment += monthlyBudget;
      }
      if (investFirstBalance > EPSILON) {
        const interest = investFirstBalance * monthlyMortgageRate;
        const amountDue = investFirstBalance + interest;
        const mortgagePaymentMade = Math.min(scheduledPayment, amountDue);
        investFirstInterest += interest;
        investFirstBalance = Math.max(0, amountDue - mortgagePaymentMade);
        investFirstInvestment += extraMonthly + scheduledPayment - mortgagePaymentMade;
        if (investFirstBalance <= EPSILON) investFirstBalance = 0;
      } else {
        investFirstInvestment += monthlyBudget;
      }
      if (month % 12 === 0 || month === months) {
        points.push({
          month,
          mortgageFirstNet: mortgageFirstInvestment - mortgageFirstBalance,
          investFirstNet: investFirstInvestment - investFirstBalance,
          mortgageFirstBalance,
          investFirstBalance
        });
      }
    }
    const mortgageFirstNet = mortgageFirstInvestment - mortgageFirstBalance;
    const investFirstNet = investFirstInvestment - investFirstBalance;
    return {
      months,
      scheduledPayment,
      monthlyBudget,
      mortgageFirstNet,
      investFirstNet,
      difference: investFirstNet - mortgageFirstNet,
      mortgageFirstInvestment,
      investFirstInvestment,
      mortgageFirstBalance,
      investFirstBalance,
      mortgageFirstInterest,
      investFirstInterest,
      interestAvoided: investFirstInterest - mortgageFirstInterest,
      mortgageFirstPayoffMonth: mortgageFirstPayoffMonth ?? months,
      netAnnualInvestmentReturn: investmentReturn - fundFee,
      points
    };
  }

